/**
 * E2E Feature: Stripe webhook signature + idempotency against the real
 * Stripe CLI (W2.10, pilot 4.3).
 *
 * What this spec proves, with zero mocks/stubs:
 *
 *   1. SIGNATURE ENFORCEMENT — the live backend rejects unsigned and
 *      mis-signed webhook POSTs (400) at
 *      `POST /api/v1/billing/webhooks/stripe/`.
 *
 *   2. CLI-SIGNED DELIVERY — a REAL `customer.subscription.deleted`
 *      event, generated by deleting the tenant's REAL remote Stripe
 *      subscription (DELETE /v1/subscriptions/:id), is forwarded by
 *      `stripe listen` (the Stripe CLI signs it with the listener's
 *      per-session `whsec_`) and the backend verifies + processes it:
 *      the local Subscription transitions to CANCELED with
 *      `canceled_at` set and exactly one `WEBHOOK_STATUS_CHANGE` audit
 *      row (details.trigger = customer.subscription.deleted).
 *
 *   3. IDEMPOTENT RE-DELIVERY — `stripe events resend <evt_id>` sends
 *      the SAME event (same evt_ id) again through the listener.  The
 *      backend's atomic processed-claim (billing/webhook_idempotency.py)
 *      must answer 200 WITHOUT re-running the handler: status stays
 *      CANCELED, `canceled_at` is unchanged, and the audit row count
 *      stays 1.
 *
 * Why the whsec file round-trip exists: `stripe listen` prints its
 * per-session signing secret AFTER the API container has booted
 * (gunicorn has no reload), so the spec writes it to
 * `./.e2e/stripe-webhook-whsec` — the repo bind mount makes the same
 * path visible at `/app/.e2e/...` inside the container, and the
 * backend reads it per request via STRIPE_WEBHOOK_SECRET_FILE
 * (billing/views.py::_webhook_secret_candidates).  A stale file from a
 * previous run can never break verification: the env-configured
 * secrets are still tried.
 *
 * Gating (matches JOURNEY-TA-BILLING-UPGRADE's W16 pattern):
 *   - E2E_STRIPE_ENABLED !== '1' → annotated skip (features/ runs in
 *     batch 7 without the flag).
 *   - Flag set but CLI / key missing → HARD failure: the operator
 *     declared the environment Stripe-wired, so a gap is a real error,
 *     never a silent skip.
 *
 * Self-heal: the test DELETES the tenant's remote subscription (that
 * is the event source).  The end-revert re-primes via
 * `ensureE2eSubscription` (a fresh ACTIVE row without stripe ids); the
 * next run's precondition change-plans it back to a priced plan, which
 * re-creates the remote subscription (the Stripe customer survives).
 */

import { execFile, spawn, type ChildProcess } from 'node:child_process';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { promisify } from 'node:util';
import { fileURLToPath } from 'node:url';

import type { Page } from '@playwright/test';
import { expect, test } from '../fixtures/guardedTest';
import { getTenantAdminUser, loginUser } from '../fixtures/auth';
import { ensureE2eSubscription } from '../fixtures/ensureE2eSubscription';

const execFileAsync = promisify(execFile);

// cwd-independent paths: Playwright compiles specs to ESM (`__dirname`
// is undefined here), so recover the spec dir from import.meta.url and
// derive the repo root from it — the Makefile target runs with cwd
// `frontend/`, which would break process.cwd()-based resolution.
const __filename = fileURLToPath(import.meta.url);
const REPO_ROOT = path.resolve(path.dirname(__filename), '../../..');
const STRIPE_CLI = process.env.STRIPE_CLI_BIN ?? path.join(REPO_ROOT, '.tools', 'bin', 'stripe');
const ENV_TEST_FILE = path.join(REPO_ROOT, '.env.test');
const WHSEC_FILE = path.join(REPO_ROOT, '.e2e', 'stripe-webhook-whsec');

const E2E_STRIPE_PLAN_SLUG = 'e2e-stripe-enterprise';
const ZERO_PRICE_PLAN_SLUG = 'e2e-unlimited';

const DEFAULT_API_PORT = process.env.E2E_WEB_PORT ? '8001' : '8000';
const API_BASE =
  process.env.E2E_API_BASE_URL ||
  (process.env.VITE_PROXY_TARGET
    ? `${process.env.VITE_PROXY_TARGET.replace(/\/$/, '')}/api/v1`
    : null) ||
  (process.env.VITE_API_BASE_URL?.startsWith('http') ? process.env.VITE_API_BASE_URL : null) ||
  `http://localhost:${DEFAULT_API_PORT}/api/v1`;
const WEBHOOK_URL = `${API_BASE}/billing/webhooks/stripe/`;

interface Subscription {
  id: string;
  plan_slug: string;
  status: string;
  stripe_subscription_id: string | null;
  stripe_customer_id: string | null;
  canceled_at: string | null;
}

interface AuditRow {
  action: string;
  resource_id: string | null;
  details_json?: Record<string, unknown> | null;
}

/** Stripe secret key from .env.test — never hardcoded, never logged. */
function loadStripeSecretKey(): string {
  let raw = '';
  try {
    raw = fs.readFileSync(ENV_TEST_FILE, 'utf8');
  } catch {
    throw new Error(
      `billing-stripe-webhook: cannot read ${ENV_TEST_FILE} — E2E_STRIPE_ENABLED=1 ` +
        `requires the repo .env.test with STRIPE_SECRET_KEY set.`
    );
  }
  for (const line of raw.split('\n')) {
    if (line.startsWith('STRIPE_SECRET_KEY=')) {
      const value = line.slice('STRIPE_SECRET_KEY='.length).trim().replace(/^"|"$/g, '');
      if (value.startsWith('sk_test_')) return value;
      throw new Error(
        `billing-stripe-webhook: STRIPE_SECRET_KEY in .env.test must be a TEST-mode key ` +
          `(sk_test_...). Refusing to run against a live key.`
      );
    }
  }
  throw new Error(
    'billing-stripe-webhook: STRIPE_SECRET_KEY not found in .env.test — ' +
      'E2E_STRIPE_ENABLED=1 requires a real test-mode key.'
  );
}

/** Playwright-safe poll: run `check` until truthy or timeout. */
async function waitFor<T>(
  check: () => Promise<T | undefined>,
  label: string,
  timeoutMs: number,
  intervalMs = 2000
): Promise<T> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const value = await check();
    if (value !== undefined) return value;
    if (Date.now() > deadline) {
      throw new Error(`billing-stripe-webhook: timed out waiting for ${label}`);
    }
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
}

async function getCurrentSub(page: Page, accessToken: string): Promise<Subscription> {
  const res = await page.request.get(`${API_BASE}/billing/subscription/current/`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });
  if (res.status() !== 200) {
    throw new Error(
      `billing-stripe-webhook: GET /billing/subscription/current/ returned ${res.status()} — ` +
        `the precondition needs a readable current subscription.`
    );
  }
  return (await res.json()) as Subscription;
}

async function changePlan(page: Page, accessToken: string, planSlug: string): Promise<void> {
  const res = await page.request.post(`${API_BASE}/billing/subscription/current/change-plan/`, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    data: { plan_slug: planSlug },
  });
  if (res.status() !== 200) {
    // intentional: diagnostic preview only — the status check below
    // decides the failure, and a missing body must not mask it.
    const body = (await res.text().catch(() => '')).slice(0, 300);
    throw new Error(
      `billing-stripe-webhook: change-plan to ${planSlug} returned ${res.status()}: ${body}`
    );
  }
}

async function countDeleteAuditRows(
  page: Page,
  accessToken: string,
  subscriptionId: string
): Promise<number> {
  const res = await page.request.get(
    `${API_BASE}/audit/audit-events/?resource_id=${subscriptionId}&action=WEBHOOK_STATUS_CHANGE&page_size=50`,
    { headers: { Authorization: `Bearer ${accessToken}` } }
  );
  if (res.status() !== 200) {
    throw new Error(
      `billing-stripe-webhook: audit list returned ${res.status()} — cannot count webhook audit rows.`
    );
  }
  const body = (await res.json()) as { results?: AuditRow[] } | AuditRow[];
  const rows = Array.isArray(body) ? body : (body.results ?? []);
  return rows.filter(
    (row) =>
      row.action === 'WEBHOOK_STATUS_CHANGE' &&
      row.details_json?.trigger === 'customer.subscription.deleted'
  ).length;
}

/** Run the pinned CLI with the stripe key; returns {stdout, stderr}. */
function runCli(args: string[], stripeApiKey: string): Promise<{ stdout: string; stderr: string }> {
  return execFileAsync(STRIPE_CLI, [...args, '--api-key', stripeApiKey], {
    timeout: 120_000,
    maxBuffer: 64 * 1024 * 1024,
  });
}

test.describe('billing-stripe-webhook: W2.10 Stripe CLI signature + idempotency', () => {
  test.setTimeout(300_000);

  test('CLI-signed delete event processed once; re-delivery idempotent', async ({ page }) => {
    test.skip(
      process.env.E2E_STRIPE_ENABLED !== '1',
      'E2E_STRIPE_ENABLED != 1 — live Stripe webhook E2E requires the flag.'
    );
    if (process.env.E2E_STRIPE_ENABLED !== '1') {
      test.info().annotations.push({
        type: 'w210-stripe-not-enabled',
        description:
          'E2E_STRIPE_ENABLED != 1 — the live Stripe webhook E2E is skipped. ' +
          'Run `make test-frontend-e2e-billing-webhook-stripe` to execute it.',
      });
      return;
    }

    // Declared-wired prerequisites — hard failures, never silent skips.
    if (!fs.existsSync(STRIPE_CLI)) {
      throw new Error(
        `billing-stripe-webhook: Stripe CLI not found at ${STRIPE_CLI}. ` +
          'Run `make ensure-stripe-cli` (or set STRIPE_CLI_BIN).'
      );
    }
    const stripeApiKey = loadStripeSecretKey();

    // ── Auth ──
    const taUser = await getTenantAdminUser();
    await loginUser(page, taUser);
    const accessToken = await page.evaluate(() => {
      const getter = (window as unknown as { __getAccessToken?: () => string | null })
        .__getAccessToken;
      return (
        (typeof getter === 'function' ? getter() : null) ?? localStorage.getItem('access_token')
      );
    });
    if (!accessToken) {
      throw new Error('billing-stripe-webhook: access_token null after loginUser.');
    }

    let listener: ChildProcess | null = null;
    try {
      // ── Step 0 — precondition: current sub on the PRICED enterprise
      // plan with a LIVE remote Stripe subscription (the event source).
      //
      // Residue-heal: a previous run leaves a fresh row on the priced
      // plan with null stripe ids (the ensure seeder uses tenant.plan,
      // which stays enterprise).  A same-plan change 400s, so move to a
      // $0 plan (local-only swap) and back — the return leg takes the
      // create branch and mints a NEW remote subscription.
      //
      // Dead-sub heal: the remote sub can die under the local row's
      // feet (Stripe test-mode EXPIRES default_incomplete subscriptions
      // — the W2.10 live finding that also produced the backend
      // resource_missing tolerance).  The liveness probe below detects
      // it; the $0 leg now clears the stale ids tolerantly, and the
      // return leg re-creates.
      // ──
      const getRemoteSub = async (subId: string) => {
        const res = await page.request.get(`https://api.stripe.com/v1/subscriptions/${subId}`, {
          headers: { Authorization: `Bearer ${stripeApiKey}` },
        });
        if (res.status() !== 200) return null;
        return (await res.json()) as { status: string };
      };
      await ensureE2eSubscription(page, accessToken);
      let current = await getCurrentSub(page, accessToken);
      const healToFreshRemoteSub = async (): Promise<Subscription> => {
        await changePlan(page, accessToken, ZERO_PRICE_PLAN_SLUG);
        await changePlan(page, accessToken, E2E_STRIPE_PLAN_SLUG);
        return getCurrentSub(page, accessToken);
      };
      if (current.plan_slug !== E2E_STRIPE_PLAN_SLUG) {
        await changePlan(page, accessToken, E2E_STRIPE_PLAN_SLUG);
        current = await getCurrentSub(page, accessToken);
      } else if (!current.stripe_subscription_id) {
        current = await healToFreshRemoteSub();
      }
      // Liveness probe: a stale/dead remote sub must be replaced BEFORE
      // the delete step, or the DELETE answers 404 and the run dies.
      let remote = current.stripe_subscription_id
        ? await getRemoteSub(current.stripe_subscription_id)
        : null;
      if (!remote || !['active', 'trialing', 'incomplete'].includes(remote.status)) {
        current = await healToFreshRemoteSub();
        remote = current.stripe_subscription_id
          ? await getRemoteSub(current.stripe_subscription_id)
          : null;
      }
      expect(
        current.stripe_subscription_id,
        'precondition: priced plan change must create a remote Stripe subscription'
      ).not.toBeNull();
      expect(current.stripe_customer_id, 'precondition: Stripe customer must exist').not.toBeNull();
      const stripeSubId = current.stripe_subscription_id as string;
      const stripeCustomerId = current.stripe_customer_id as string;

      // ── Step 0b — complete the subscription's payment (real REST).
      //
      // The backend creates the sub with payment_behavior=default_incomplete
      // (change-plan has no payment capture).  In Stripe TEST mode such a
      // subscription EXPIRES (incomplete_expired) and can no longer be
      // deleted — the exact failure the earlier runs hit.  Attaching the
      // canonical test card (tok_visa → pm_card_visa) and paying the open
      // first invoice is the real-world "customer adds a card" flow; it
      // flips the sub to `active`, which does not expire.
      // ──
      // NOTE: Stripe's REST API requires application/x-www-form-urlencoded
      // on these write endpoints (JSON answers "Invalid request" — the
      // live run-6 finding), hence `form:` not `data:`.
      const pmRes = await page.request.post('https://api.stripe.com/v1/payment_methods', {
        headers: { Authorization: `Bearer ${stripeApiKey}` },
        form: { type: 'card', 'card[token]': 'tok_visa' },
      });
      expect(pmRes.status(), 'creating a test payment method').toBe(200);
      const paymentMethod = (await pmRes.json()) as { id: string };
      const attachRes = await page.request.post(
        `https://api.stripe.com/v1/payment_methods/${paymentMethod.id}/attach`,
        {
          headers: { Authorization: `Bearer ${stripeApiKey}` },
          form: { customer: stripeCustomerId },
        }
      );
      expect(attachRes.status(), 'attaching the payment method to the customer').toBe(200);
      const setDefaultRes = await page.request.post(
        `https://api.stripe.com/v1/customers/${stripeCustomerId}`,
        {
          headers: { Authorization: `Bearer ${stripeApiKey}` },
          form: { 'invoice_settings[default_payment_method]': paymentMethod.id },
        }
      );
      expect(setDefaultRes.status(), 'setting the default payment method').toBe(200);
      const invoiceRes = await page.request.get(
        `https://api.stripe.com/v1/invoices?subscription=${stripeSubId}&status=open&limit=1`,
        { headers: { Authorization: `Bearer ${stripeApiKey}` } }
      );
      expect(invoiceRes.status(), 'listing the open invoice').toBe(200);
      const invoiceBody = (await invoiceRes.json()) as { data?: { id: string }[] };
      const openInvoiceId = invoiceBody.data?.[0]?.id;
      if (openInvoiceId) {
        const payRes = await page.request.post(
          `https://api.stripe.com/v1/invoices/${openInvoiceId}/pay`,
          { headers: { Authorization: `Bearer ${stripeApiKey}` } }
        );
        expect(payRes.status(), 'paying the open invoice').toBe(200);
      }
      await waitFor(
        async () => {
          const sub = await getRemoteSub(stripeSubId);
          return sub?.status === 'active' ? sub.status : undefined;
        },
        `remote subscription ${stripeSubId} to become active`,
        60_000
      );

      // ── Step 1 — signature enforcement (negative probes) ──
      const noSig = await page.request.post(WEBHOOK_URL, { data: '{}' });
      expect(noSig.status(), 'unsigned webhook POST must be rejected').toBe(400);
      const badSig = await page.request.post(WEBHOOK_URL, {
        data: '{}',
        headers: { 'Stripe-Signature': 't=1,v1=deadbeef' },
      });
      expect(badSig.status(), 'mis-signed webhook POST must be rejected').toBe(400);

      // ── Step 2 — listener + whsec propagation ──
      listener = spawn(
        STRIPE_CLI,
        [
          'listen',
          '--forward-to',
          WEBHOOK_URL,
          '--events',
          'customer.subscription.deleted',
          '--api-key',
          stripeApiKey,
        ],
        { stdio: ['ignore', 'pipe', 'pipe'] }
      );
      let listenerLog = '';
      listener.stdout?.on('data', (chunk) => {
        listenerLog += chunk.toString();
      });
      listener.stderr?.on('data', (chunk) => {
        listenerLog += chunk.toString();
      });

      const whsec = await waitFor(
        async () => {
          const match = listenerLog.match(/webhook signing secret is (whsec_[A-Za-z0-9]+)/);
          return match?.[1];
        },
        'stripe listen Ready line',
        90_000
      );
      fs.mkdirSync(path.dirname(WHSEC_FILE), { recursive: true });
      fs.writeFileSync(WHSEC_FILE, whsec);
      console.log(`[billing-stripe-webhook] listener ready; whsec propagated to ${WHSEC_FILE}`);

      // ── Step 3 — real event: DELETE the remote subscription ──
      // page.request.delete (Playwright's APIRequestContext) — the same
      // request surface every other call in this spec uses; its
      // .status()/.json() shape avoids the global-fetch ambiguity.
      const deleteRes = await page.request.delete(
        `https://api.stripe.com/v1/subscriptions/${stripeSubId}`,
        { headers: { Authorization: `Bearer ${stripeApiKey}` } }
      );
      if (deleteRes.status() !== 200) {
        // intentional: diagnostic preview only — the status check above
        // decides the failure, and a missing body must not mask it.
        const body = await deleteRes.text().catch(() => '');
        throw new Error(
          `billing-stripe-webhook: DELETE /v1/subscriptions/${stripeSubId} returned ` +
            `${deleteRes.status()}: ${body.slice(0, 400)}`
        );
      }
      const deletedBody = await deleteRes.json();
      expect(deletedBody.id).toBe(stripeSubId);

      // ── Step 4 — backend processed the CLI-signed event ──
      // The audit count is a DELTA, not an absolute: the subscription
      // row is REUSED across runs (the heal mutates the same row), so
      // WEBHOOK_STATUS_CHANGE rows from earlier runs accumulate on the
      // same resource_id — which is the LOCAL row id, not the Stripe
      // sub id.  This run's handler must add EXACTLY one.
      const auditRowsBeforeDelete = await countDeleteAuditRows(page, accessToken, current.id);
      const canceled = await waitFor(
        async () => {
          const sub = await getCurrentSub(page, accessToken);
          return sub.status === 'CANCELED' ? sub : undefined;
        },
        'local subscription to reach CANCELED via webhook',
        120_000
      );
      expect(canceled.canceled_at, 'canceled_at must be set by the webhook handler').not.toBeNull();
      const canceledAt = canceled.canceled_at as string;
      const auditRowsAfterFirst = await waitFor(
        async () => {
          const count = await countDeleteAuditRows(page, accessToken, canceled.id);
          return count >= auditRowsBeforeDelete + 1 ? count : undefined;
        },
        'one new WEBHOOK_STATUS_CHANGE audit row',
        60_000
      );
      expect(auditRowsAfterFirst).toBe(auditRowsBeforeDelete + 1);

      // ── Step 5 — find the real event id (eventual consistency) ──
      const eventId = await waitFor(
        async () => {
          let stdout = '';
          try {
            const result = await runCli(
              ['events', 'list', '--type', 'customer.subscription.deleted', '--limit', '100'],
              stripeApiKey
            );
            stdout = result.stdout;
          } catch {
            // intentional: the Stripe event log is eventually consistent —
            // a transient CLI/API failure here just extends the poll budget.
          }
          try {
            const jsonStart = stdout.indexOf('{');
            const parsed = JSON.parse(stdout.slice(jsonStart)) as {
              data?: { id: string; data?: { object?: { id?: string } } }[];
            };
            const event = (parsed.data ?? []).find((evt) => evt.data?.object?.id === stripeSubId);
            return event?.id;
          } catch {
            return undefined;
          }
        },
        `customer.subscription.deleted event for ${stripeSubId} in the Stripe event log`,
        90_000,
        4000
      );

      // ── Step 6 — re-deliver the SAME event (idempotency probe) ──
      // execFileAsync throws on a non-zero exit — a successful CLI
      // return IS the assertion that Stripe accepted the resend.
      await runCli(['events', 'resend', eventId], stripeApiKey);

      // The listener logs each forwarded delivery's HTTP status.  Wait
      // for a SECOND [2xx] delivery line (first = original forward).
      await waitFor(
        async () => {
          const deliveries = listenerLog.match(/\[(\d+)\] POST/g)?.length ?? 0;
          return deliveries >= 2 ? deliveries : undefined;
        },
        'a second (re-sent) webhook delivery through the listener',
        90_000
      );
      // Give the duplicate (if the claim failed) a chance to misbehave.
      await new Promise((resolve) => setTimeout(resolve, 10_000));

      // ── Step 7 — idempotency assertions ──
      //
      // If the claim worked, the handler never re-ran: status stays
      // CANCELED, canceled_at is byte-identical, audit count stays 1.
      // (A duplicate delete with a NEW event id WOULD overwrite
      // canceled_at and emit a second audit row — that is exactly the
      // double-processing this spec proves absent.)
      const after = await getCurrentSub(page, accessToken);
      expect(after.status).toBe('CANCELED');
      expect(after.canceled_at).toBe(canceledAt);
      const auditRowsAfterResend = await countDeleteAuditRows(page, accessToken, canceled.id);
      expect(auditRowsAfterResend).toBe(auditRowsBeforeDelete + 1);
    } finally {
      // ── Teardown: listener + whsec file + remote-state self-heal ──
      if (listener) {
        listener.kill('SIGTERM');
        await new Promise((resolve) => setTimeout(resolve, 1000));
        if (!listener?.killed) listener?.kill('SIGKILL');
      }
      try {
        fs.unlinkSync(WHSEC_FILE);
      } catch {
        // intentional: best-effort teardown — the file may already be
        // absent (never written, or a prior run removed it).
      }
      if (accessToken) {
        await ensureE2eSubscription(page, accessToken);
      }
    }
  });
});
